  const entry = r[0];
  assert.equal(typeof entry.rate, 'number');
  assert.equal(typeof entry.base, 'number');
  assert.equal(typeof entry.vat, 'number');
  assert(entry.base > 0);
  assert(entry.vat > 0);
});

test('vatSummary handles large amounts correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const r = vatSummary([issued.value]);
  assert.equal(r[0].vat, totals.vat);
});

test('vatSummary does not mutate input array', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const invoices = [issued.value];
  const original = JSON.stringify(invoices);
  vatSummary(invoices);
  assert.equal(JSON.stringify(invoices), original);
});

test('vatSummary handles mixed status invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  const paid2 = recordPayment(issued2.value, { amount: 9771, date: '2026-10-09' });

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-09',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const totals1 = invoiceTotals(issued1.value);
  const totals2 = invoiceTotals(paid2.value);
  const expectedBase = (totals1.subtotal - totals1.discount) + (totals2.subtotal - totals2.discount);

  const r = vatSummary([issued1.value, paid2.value, inv3.value]);
  assert.equal(r.length, 1);
  assert.equal(r[0].base, expectedBase);
});
